#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int maxn=6000;
const int inf=INT_MAX;
const ll inff=1e18;
#define pii pair<int,int>
#define mkp make_pair
#define F first
#define S second
#define pb push_back
#define sz(v) ((int)(v).size())
#define all(v) (v).begin(),(v).end()
#define IOS ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);
#define int ll
// #define endl '\n'

int n,s,t;
struct edge
{
    int to,cap,cost,rev;
};
vector<edge> G[maxn];
int dist[maxn];
int prevv[maxn],preve[maxn];
int inq[maxn];

void initialize(int _n,int _s,int _t)
{
    for (int i=0;i<=_n;i++) G[i].clear();
    n=_n;
    s=_s;
    t=_t;
}

void create_edge(int from,int to,int cap,int cost)
{
    G[from].push_back({to,cap,cost,(int)G[to].size()});
    G[to].push_back({from,0,-cost,(int)G[from].size()-1});
}

int compute_min_cost_flow(int flow_needed)
{
    int total_cost=0;
    while (flow_needed>0)
    {
        fill(dist,dist+n,inff);
        dist[s]=0;
        queue<int> q;
        q.push(s);
        inq[s]=1;
        while (!q.empty())
        {
            int u=q.front();
            q.pop();
            inq[u]=0;
            for (int i=0;i<sz(G[u]);i++)
            {
                auto &e=G[u][i];
                if (e.cap>0&&dist[u]+e.cost<dist[e.to])
                {
                    dist[e.to]=dist[u]+e.cost;
                    prevv[e.to]=u;
                    preve[e.to]=i;
                    if (!inq[e.to]) { inq[e.to]=1; q.push(e.to); }
                }
            }
        }

        if (dist[t]==inff) return -1;

        int d=flow_needed;
        for (int v=t;v!=s;v=prevv[v])
        {
            d=min(d,G[prevv[v]][preve[v]].cap);
        }
        flow_needed-=d;
        total_cost+=d*dist[t];
        for (int v=t;v!=s;v=prevv[v])
        {
            auto &e=G[prevv[v]][preve[v]];
            e.cap-=d;
            G[v][e.rev].cap+=d;
        }
    }
    return total_cost;
}

int N,M,K,C,D,X,Y;
int A[58];
vector<int> H[57];

int main()
{
    IOS
    cin>>N>>M>>K>>C>>D;
    for (int i=1;i<=K;i++)
    {
        cin>>X;
        A[X]++;
    }
    for (int i=1;i<=M;i++)
    {
        cin>>X>>Y;
        H[X].push_back(Y);
        H[Y].push_back(X);
    }

    initialize(5103,0,5101);
    for (int i=2;i<=N;i++) create_edge(0,i,A[i],0);
    for (int i=0;i<=100;i++)
    {
        for (int l=1;l<=N;l++)
        {
            create_edge(50*i+l,50*(i+1)+l,K,0);
            for (int j:H[l])
            {
                for (int k=1;k<=K;k++)
                {
                    create_edge(50*i+l,50*(i+1)+j,1,D*(2*k-1));
                }
            }
        }
    }
    for (int i=1;i<=101;i++) create_edge(50*i+1,5101,K,C*i);
    cout<<compute_min_cost_flow(K)<<endl;
}
